<script>
    function createGrid(gridSize = 70, gridColor = 'white') {
        const svg = document.getElementById('grid');
        const gridGroup = document.getElementById('gridLines');
        if (!svg || !gridGroup) return;

        const bounds = svg.getBoundingClientRect();
        const width = Math.ceil(bounds.width || 0);
        const height = Math.ceil(bounds.height || 0);
        if (width < 1 || height < 1) return;

        // Clear previous grid
        while (gridGroup.firstChild) gridGroup.removeChild(gridGroup.firstChild);

        // Keep SVG coordinates in sync with its rendered size
        svg.setAttribute('viewBox', `0 0 ${width} ${height}`);

        // Resize the fade mask to match
        const maskRect = document.querySelector('#fadeMask rect');
        if (maskRect) {
            maskRect.setAttribute('width', String(width));
            maskRect.setAttribute('height', String(height));
        }

        const fragment = document.createDocumentFragment();
        for (let x = 0; x <= width; x += gridSize) {
            for (let y = 0; y <= height; y += gridSize) {
                const rect = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
                rect.setAttribute('x', String(x));
                rect.setAttribute('y', String(y));
                rect.setAttribute('width', String(gridSize));
                rect.setAttribute('height', String(gridSize));
                rect.setAttribute('fill', 'none');
                rect.setAttribute('stroke', gridColor);
                rect.setAttribute('stroke-width', '1');
                fragment.appendChild(rect);
            }
        }

        gridGroup.appendChild(fragment);
    }

    document.addEventListener('DOMContentLoaded', function() {
        createGrid(70, 'white');

        // Re-render on resize (debounced)
        let resizeTimer;
        window.addEventListener('resize', function() {
            clearTimeout(resizeTimer);
            resizeTimer = setTimeout(function() {
                createGrid(70, 'white');
            }, 150);
        });
    });

    document.addEventListener('DOMContentLoaded', function() {
        const form = document.getElementById('form1');
        const submitButton = document.getElementById('submitButton');

        form.addEventListener('submit', function() {
            // Disable the submit button on form submission
            submitButton.disabled = true;
            submitButton.textContent = 'Submitting...'; // Optional: Update button text
        });

        // Re-enable button if there are validation errors (page reloads with errors)
        @if($errors -> any())
        submitButton.disabled = false;
        submitButton.textContent = 'Get a Free Class';
        @endif
    });
</script>

