            scrollbar: {
                el: ".swiper-scrollbar",
                hide: false,
            },
        });
    });
</script>

<script>
    const input = document.querySelector("#phone");
    const submitBtn = document.querySelector("#submitButton");
    let iti;

    const setUpPhoneInput = (countryCode = 'pk') => {
        console.log("Initializing phone input with country:", countryCode);

        iti = window.intlTelInput(input, {
            initialCountry: countryCode,
            utilsScript: "https://cdn.jsdelivr.net/npm/intl-tel-input@17.0.8/build/js/utils.js",
        });

        input.addEventListener("countrychange", () => {
            const newCountry = iti.getSelectedCountryData().iso2;
            localStorage.setItem("userCountry", newCountry); // Always update localStorage
            validateOnBlur();
        });

        input.addEventListener("blur", validateOnBlur);
        input.addEventListener("change", resetValidation);
        input.addEventListener("keyup", resetValidation);
    };

    const detectCountryFromLocation = () => {
        if (!navigator.geolocation) {
            console.warn("Geolocation not supported. Using fallback.");
            setUpPhoneInput("pk");
            return;
        }

        navigator.geolocation.getCurrentPosition(
            (pos) => {
                const {
                    latitude,
                    longitude
                } = pos.coords;
                console.log("Detected location:", latitude, longitude);

                // Use Nominatim reverse geocoding
                fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${latitude}&lon=${longitude}`)
                    .then(res => res.json())
                    .then(data => {
                        const countryCode = (data?.address?.country_code || "pk").toLowerCase();
                        console.log("Reverse geocoded country:", countryCode);
                        localStorage.setItem("userCountry", countryCode); // Update localStorage
                        setUpPhoneInput(countryCode);
                    })
                    .catch(err => {
                        console.error("Geolocation reverse fetch failed", err);
                        setUpPhoneInput("pk");
                    });
            },
            (err) => {
                console.warn("Geolocation blocked or failed", err);
                setUpPhoneInput("pk");
            }, {
                timeout: 7000
            }
        );
    };

    const resetValidation = () => {
        input.classList.remove("is-invalid", "is-valid", "error");
        submitBtn.disabled = false;
    };

    const validateOnBlur = () => {
        resetValidation();
        const value = input.value.trim();
        if (value && iti) {
            if (iti.isValidNumber()) {
                const countryData = iti.getSelectedCountryData();
                document.querySelector("#area_code").value = countryData.dialCode || "";
                input.classList.add("is-valid");
                submitBtn.disabled = false;
            } else {
                input.classList.add("is-invalid", "error");
                document.querySelector("#area_code").value = "";
                submitBtn.disabled = true;
            }
        }
    };

    // 🚀 Entry point
    detectCountryFromLocation();
</script>